import React from 'react';
import { Typography, Card, Space, Button, Tag, Row, Col, List } from 'antd';
import { 
  CrownOutlined, 
  CheckOutlined, 
  StarOutlined,
  GiftOutlined 
} from '@ant-design/icons';

const { Title, Paragraph } = Typography;

const Payments: React.FC = () => {
  const plans = [
    {
      name: 'Базовый',
      price: 'Бесплатно',
      features: [
        'Базовые промпты',
        'Ограниченное количество сообщений',
        'Базовая поддержка'
      ],
      current: false,
      popular: false
    },
    {
      name: 'Premium',
      price: '299₽/месяц',
      features: [
        'Все базовые промпты',
        'Premium промпты',
        'Неограниченные сообщения',
        'Приоритетная поддержка',
        'Расширенные настройки LLM'
      ],
      current: true,
      popular: true
    },
    {
      name: 'Enterprise',
      price: '999₽/месяц',
      features: [
        'Все функции Premium',
        'Индивидуальные промпты',
        'API доступ',
        'Персональный менеджер',
        'Белый лейбл'
      ],
      current: false,
      popular: false
    }
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <Title level={2}>
        💎 Подписка
      </Title>
      <Paragraph>
        Выберите план, который подходит именно вам
      </Paragraph>

      <Row gutter={[24, 24]}>
        {plans.map((plan) => (
          <Col xs={24} md={8} key={plan.name}>
            <Card
              title={
                <Space direction="vertical" style={{ width: '100%', textAlign: 'center' }}>
                  <Title level={3} style={{ margin: 0 }}>
                    {plan.name}
                  </Title>
                  <Title level={2} style={{ margin: 0 }}>
                    {plan.price}
                  </Title>
                  {plan.popular && (
                    <Tag color="gold" icon={<StarOutlined />}>
                      Популярный
                    </Tag>
                  )}
                  {plan.current && (
                    <Tag color="green" icon={<CheckOutlined />}>
                      Текущий план
                    </Tag>
                  )}
                </Space>
              }
              style={{ border: plan.popular ? '2px solid var(--sp-accent, #faad14)' : '1px solid var(--sp-border-color, #d9d9d9)', position: 'relative' }}
            >
              <List
                dataSource={plan.features}
                renderItem={(feature) => (
                  <List.Item>
                    <List.Item.Meta
                      avatar={<CheckOutlined style={{ color: '#52c41a' }} />}
                      title={feature}
                    />
                  </List.Item>
                )}
              />
              
              <div style={{ marginTop: 'var(--sp-spacing-sm)' }}>
                {plan.current ? (
                  <Button type="primary" block disabled>
                    Текущий план
                  </Button>
                ) : (
                  <Button type="primary" block>
                    {plan.name === 'Базовый' ? 'Активировать' : 'Выбрать план'}
                  </Button>
                )}
              </div>
            </Card>
          </Col>
        ))}
      </Row>

      <Card style={{ marginTop: 'var(--sp-spacing-md, 32px)' }}>
        <Title level={3}>
          🎁 Специальные предложения
        </Title>
        <Row gutter={[16, 16]}>
          <Col xs={24} md={12}>
            <Card size="small" title="🎯 Годовая подписка" hoverable>
              <Paragraph>
                <strong>Скидка 20%</strong> при оплате за год
              </Paragraph>
              <Button type="primary" size="small">
                Подробнее
              </Button>
            </Card>
          </Col>
          <Col xs={24} md={12}>
            <Card size="small" title="👥 Командная подписка" hoverable>
              <Paragraph>
                <strong>Скидка до 40%</strong> для команд от 5 человек
              </Paragraph>
              <Button type="primary" size="small">
                Подробнее
              </Button>
            </Card>
          </Col>
        </Row>
      </Card>

      <Card style={{ marginTop: 'var(--sp-spacing-sm)' }}>
        <Title level={4}>❓ Часто задаваемые вопросы</Title>
        <List
          size="large"
          dataSource={[
            {
              question: 'Можно ли отменить подписку?',
              answer: 'Да, вы можете отменить подписку в любое время в настройках профиля.'
            },
            {
              question: 'Что происходит при отмене?',
              answer: 'Вы сохраняете доступ до конца оплаченного периода, затем переходите на базовый план.'
            },
            {
              question: 'Есть ли пробный период?',
              answer: 'Да, Premium план доступен бесплатно первые 7 дней.'
            }
          ]}
          renderItem={(item) => (
            <List.Item>
              <List.Item.Meta
                title={item.question}
                description={item.answer}
              />
            </List.Item>
          )}
        />
      </Card>
    </div>
  );
};

export default Payments;
